const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logIdx, setLogIdx] = useState(0);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  const logs = [
    "SESSION: INITIALIZING KERNEL...",
    "HANDSHAKE: RSA-4096 VALIDATED",
    "NODE: JKT-S01 SIGNAL STABLE",
    "PROTOCOL: ZERO-TRUST ENABLED"
  ];

  useEffect(() => {
    // Init DB
    seedDatabase();
    const timer = setInterval(() => setLogIdx(i => (i + 1) % logs.length), 2500);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();

      setTimeout(() => {
        if (user && user.password === formData.password) {
          onAuthSuccess(user);
        } else {
          setLoading(false);
          setError("NEURAL ID MISMATCH: ACCESS TERMINATED");
        }
      }, 1500); // Simulated delay for effect
    } catch (err) {
      setLoading(false);
      setError("DATABASE CONNECTION ERROR");
    }
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1800);
  };

  const handleVerifyFinal = async () => {
    if (otp !== generatedOtp) {
      setError("PARITY ERROR: TOKEN SEQUENCE REJECTED");
      setOtp('');
      return;
    }
    setLoading(true);

    try {
      const existingUser = await db.users.where('email').equals(formData.email).first();
      if (existingUser) {
        setLoading(false);
        setError("NODE ALREADY REGISTERED");
        return;
      }

      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        password: formData.password,
        role: formData.role,
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`,
        memberSince: new Date().toISOString(),
        trustScore: 88,
        verified: false
      };

      const id = await db.users.add(newUser);
      const createdUser = { ...newUser, id };

      setTimeout(() => {
        onAuthSuccess(createdUser);
      }, 1500);
    } catch (err) {
      setLoading(false);
      setError("REGISTRATION FAILED");
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] dark:bg-[#01100d] flex flex-col items-center justify-center p-6 relative overflow-hidden transition-colors duration-1000">

      {/* IMMERSIVE BACKGROUND CAPTURE */}
      <div className="absolute inset-0 bg-neural-mesh opacity-40 dark:opacity-10 pointer-events-none"></div>
      <div className="absolute inset-0 desktop-grid opacity-20 dark:opacity-10 pointer-events-none"></div>
      <div className="absolute top-[-20%] right-[-10%] w-[1000px] h-[1000px] bg-primary-500/10 dark:bg-primary-500/5 rounded-full blur-[180px] animate-blob"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-[800px] h-[800px] bg-blue-500/10 dark:bg-blue-500/5 rounded-full blur-[160px] animate-blob animation-delay-4000"></div>

      {/* OTP SIMULATION NOTIFICATION */}
      {showIncomingSim && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[300] w-full max-w-sm px-4 animate-pop-in">
           <div className="bg-white/80 dark:bg-emerald-900/40 backdrop-blur-3xl border-2 border-primary-500/30 rounded-[3rem] p-8 shadow-[0_40px_80px_rgba(16,185,129,0.2)] flex items-start gap-6 relative overflow-hidden group ring-1 ring-primary-500/10">
              <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 to-transparent"></div>
              <div className="w-16 h-16 bg-primary-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-bounce shadow-[0_0_30px_rgba(16,185,129,0.5)] relative z-10">
                 <BellRing size={32}/>
              </div>
              <div className="flex-1 space-y-2 relative z-10">
                 <p className="text-[0.7rem] font-black text-primary-600 dark:text-primary-400 uppercase tracking-widest">Neural Link Service</p>
                 <p className="text-sm font-bold text-midnight dark:text-white tracking-tight leading-tight">Verification sequence dispatched:</p>
                 <p className="text-3xl font-black text-primary-600 dark:text-white tracking-[0.25em] drop-shadow-[0_0_15px_rgba(16,185,129,0.3)]">{generatedOtp}</p>
                 <button onClick={() => setShowIncomingSim(false)} className="text-[0.6rem] font-black text-primary-600/60 dark:text-emerald-400/60 uppercase tracking-widest mt-3 hover:text-primary-600 dark:hover:text-white transition-colors flex items-center gap-2 bg-primary-500/5 py-1.5 px-3 rounded-full w-fit border border-primary-500/10">
                   <XIcon size={12}/> Dismiss
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-lg relative z-10 space-y-12">
        {/* BRAND HEADER */}
        <div className="flex flex-col items-center gap-8">
          <div className="relative group cursor-pointer" onClick={() => window.location.reload()}>
            <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-[60px] animate-pulse group-hover:bg-primary-500/40 transition-all"></div>
            <SurePathLogo className="w-24 h-24 relative animate-hologram drop-shadow-[0_0_40px_rgba(16,185,129,0.3)] transition-transform duration-1000 group-hover:scale-110" />
          </div>
          <div className="text-center space-y-2">
            <h1 className="text-5xl font-black tracking-[-0.05em] uppercase text-midnight dark:text-white leading-none">
              SURE<span className="text-primary-500 text-glow-emerald">PATH</span>
            </h1>
            <div className="flex items-center justify-center gap-3">
               <div className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-ping"></div>
               <p className="text-[0.7rem] font-black text-gray-400 dark:text-gray-500 uppercase tracking-[0.6em]">Secure Access Hub</p>
            </div>
          </div>
        </div>

        {/* AUTH BOX */}
        <div className="glass-titan rounded-[4.5rem] p-10 lg:p-14 border-4 border-white/80 dark:border-white/5 shadow-[0_80px_120px_-30px_rgba(0,0,0,0.1)] dark:shadow-[0_80px_120px_-30px_rgba(0,0,0,0.8)] bg-white/70 dark:bg-black/60 backdrop-blur-[60px] relative overflow-hidden group">

          {/* SCAN LINE EFFECT */}
          <div className="absolute top-0 left-0 w-full h-2 bg-primary-500 shadow-[0_0_25px_#10b981] animate-scan-line opacity-20 pointer-events-none"></div>

          {loading && (
            <div className="absolute inset-0 bg-white/95 dark:bg-black/95 backdrop-blur-3xl z-50 flex flex-col items-center justify-center gap-10 animate-fade-in">
               <div className="relative">
                  <div className="w-32 h-32 bg-primary-500/5 rounded-[4.5rem] flex items-center justify-center border-2 border-primary-500/20 shadow-2xl">
                    <Fingerprint className="text-primary-500 animate-pulse" size={80} />
                  </div>
                  <div className="absolute inset-[-20px] border-2 border-primary-500/10 rounded-[5.5rem] animate-ping opacity-40"></div>
                  <div className="absolute inset-[-40px] border border-primary-500/5 rounded-[6.5rem] animate-reverse-spin duration-[10s]"></div>
               </div>
               <div className="text-center space-y-3">
                  <p className="text-[1rem] font-black text-midnight dark:text-white uppercase tracking-[0.6em] animate-pulse">Decrypting Path</p>
                  <div className="flex items-center justify-center gap-2">
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/30 animate-bounce"></span>
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/30 animate-bounce delay-150"></span>
                     <span className="w-1.5 h-1.5 rounded-full bg-primary-500/30 animate-bounce delay-300"></span>
                  </div>
               </div>
            </div>
          )}

          {mode === 'VERIFY' ? (
            <div className="space-y-12 animate-fade-in text-center py-4">
                {/* ... (Verification UI - unchanged visually) ... */}
                <div className="space-y-6">
                    <div className="relative group">
                       <input 
                        maxLength={6}
                        placeholder="••••••"
                        className="w-full py-10 bg-gray-50 dark:bg-white/[0.03] border-2 border-gray-100 dark:border-white/5 rounded-[3.5rem] text-center text-6xl font-black tracking-[0.5em] text-primary-500 outline-none focus:border-primary-500 focus:bg-white transition-all placeholder:opacity-5 shadow-inner"
                        value={otp}
                        onChange={(e) => {
                          setOtp(e.target.value.replace(/\D/g, ''));
                          setError(null);
                        }}
                      />
                      <div className="absolute inset-0 border-4 border-primary-500/10 rounded-[3.5rem] pointer-events-none group-focus-within:border-primary-500/20 group-focus-within:animate-pulse"></div>
                    </div>
                    {error && <p className="text-[0.7rem] font-black text-rose-500 uppercase tracking-[0.2em] animate-shake bg-rose-500/5 py-4 rounded-3xl border border-rose-500/20">{error}</p>}
