                    className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-black rounded-[3rem] font-black uppercase text-base tracking-[0.4em] shadow-[0_30px_60px_rgba(0,0,0,0.2)] disabled:opacity-20 active:scale-95 transition-all hover:bg-primary-600 dark:hover:bg-gray-100 border border-white/10 group/btn"
                  >
                    Authorize Node <ArrowRight size={22} className="inline-block ml-3 group-hover/btn:translate-x-2 transition-transform text-primary-500"/>
                  </button>
                  <button onClick={() => {setMode('REGISTER'); setOtp('');}} className="text-[0.7rem] font-black text-gray-400 uppercase tracking-widest hover:text-primary-500 transition-colors border-b-2 border-transparent hover:border-primary-500/20 pb-1">Reset Handshake</button>
                </div>
