                    {[
                      { id: 'LOGIN', label: 'Access Gate', icon: Lock },
                      { id: 'REGISTER', label: 'Enroll Node', icon: UserPlusIcon }
                    ].map((m) => (
                    <button 
                        key={m.id}
                        onClick={() => { setMode(m.id as any); setError(null); }}
                        className={`flex-1 py-5 rounded-[2rem] text-[0.7rem] font-black uppercase tracking-widest transition-all duration-700 flex items-center justify-center gap-3 relative z-10 ${mode === m.id ? 'text-primary-600 dark:text-primary-400' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
                    >
                        <m.icon size={18} strokeWidth={2.5}/> {m.label}
