                                  {r === UserRole.CUSTOMER ? 'MEMBER' : 'PARTNER'}
                                </button>
                              ))}
                           </div>
                        </div>
                      </div>
                    )}

                    <InputField 
                        icon={Globe} label="Neural Identifier" type="text" name="email" placeholder="registry-node@surepath.ai" value={formData.email} onChange={(n:any, v:any)=>setFormData(f=>({...f,email:v}))} 
                    />

                    <InputField 
                        icon={Binary} label="Encryption Key" type="password" name="password" placeholder="••••••••" value={formData.password} onChange={(n:any, v:any)=>setFormData(f=>({...f,password:v}))} showPass={showPass} setShowPass={setShowPass}
                    />

                    {error && <p className="text-[0.7rem] font-black text-rose-500 uppercase tracking-[0.2em] text-center animate-shake bg-rose-500/5 py-4 rounded-[2rem] border border-rose-500/20">{error}</p>}

                    <div className="space-y-6 pt-4">
                      <button type="submit" className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-midnight rounded-[3rem] font-black uppercase text-base tracking-[0.4em] shadow-[0_30px_60px_rgba(0,0,0,0.1)] dark:shadow-[0_30px_60px_rgba(0,0,0,0.5)] flex items-center justify-center gap-6 transition-all hover:bg-primary-600 dark:hover:bg-gray-100 hover:scale-[1.02] active:scale-95 group border border-midnight/10 dark:border-white/10 relative overflow-hidden">
