export const analyzeVehicleSurvey = async (images: {id: string, data: string}[]): Promise<SurveyAnalysisResult> => {
  try {
    const ai = getAi();
    const imageParts = images.map(img => {
      const data = img.data.includes(',') ? img.data.split(',')[1] : img.data;
      return { inlineData: { mimeType: 'image/jpeg', data } };
    });

    const prompt = `Lakukan audit pra-asuransi (Underwriting Risk Assessment) yang sangat ketat dan faktual menggunakan Computer Vision. Anda adalah Chief Underwriter.

    Tugas: Analisa kondisi fisik kendaraan dari foto-foto yang diberikan.

    1. Identifikasi Kerusakan (Damage Detection):
       - Periksa setiap panel: Bumper, Pintu, Fender, Kap Mesin, Atap, Kaca.
       - Cari: Goresan (Scratch), Penyok (Dent), Pecah (Crack), Karat (Rust).
       - Jika tidak ada kerusakan, nyatakan "Mulus / Clean".

    2. Penilaian Skor (Scoring 0-100):
       - Skor 100: Mobil kondisi "Showroom New" (Tanpa cacat sedikitpun).
       - Skor 90-99: Kondisi sangat baik, mungkin ada swirl mark mikro tak kasat mata.
       - Skor 80-89: Kondisi baik, ada goresan rambut sangat halus (normal wear).
       - Skor < 80: Terdapat kerusakan VISUAL yang jelas (penyok, goresan dalam, cat terkelupas).

       PENTING: JANGAN BERIKAN SKOR DI ATAS 80 JIKA ADA KERUSAKAN TERLIHAT.

    3. Deteksi Fraud & Kualitas:
       - Pastikan foto bukan dari layar komputer/HP lain.
       - Pastikan foto diambil di lokasi nyata (outdoor/garage).

    Output JSON Wajib:
    {
      "score": number,
      "summary": "Kesimpulan underwriting singkat (Bahasa Indonesia). Contoh: 'Unit dalam kondisi baik dengan minor scratch di bumper depan.'",
      "underwritingReport": "Laporan naratif faktual dan detail per panel yang dianalisa. Gunakan bahasa profesional asuransi. Sebutkan bagian mana yang mulus dan bagian mana yang ada concern.",
      "detailedIssues": [
        { "part": "Nama Bagian (Misal: Bumper Depan)", "description": "Deskripsi kerusakan faktual", "severity": "Minor" | "Moderate" | "Severe", "scorePenalty": number }
      ],
      "photoFlags": [
        { "id": "id_foto", "status": "OK" | "FRAUD_DETECTED" | "POOR_QUALITY", "reason": "Reason" }
      ],
      "auditVerdict": "CLEAN" | "REVIEW_REQUIRED" | "REJECTED"
    }

    Logic Verdict:
    - CLEAN: Score >= 85
    - REVIEW_REQUIRED: Score < 85 (Termasuk < 80 yang butuh manual assessment)
    - REJECTED: Indikasi Fraud / Kerusakan Total / Foto Invalid.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }, ...imageParts.map(p => p)] },
      config: { responseMimeType: 'application/json', temperature: 0.1 }
    });

    const data = JSON.parse(response.text);

    const flagsWithIds = data.photoFlags?.map((flag: any, index: number) => ({
      ...flag,
      id: images[index]?.id || `img_${index}`
    }));

    return { success: true, ...data, photoFlags: flagsWithIds };
  } catch (e) { 
    console.error("Vehicle Survey AI Error:", e);
    return { success: false, error: "Gagal menghubungkan ke Neural Engine." }; 
  }
};

