                  {survey.verdict === 'REJECTED' ? 'Registry Node terminated due to risk mismatch.' : isManualPending ? 'Policy issuance pending manual assessment results.' : 'Neural verification successful. Ready for deployment.'}
               </p>
            </div>
          </div>

          <div className="p-10 bg-white dark:bg-white/5 border-2 border-black/5 dark:border-white/5 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.05)] space-y-8 relative overflow-hidden">
