                      <div className="p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border border-emerald-200 dark:border-emerald-900/30 text-center space-y-4">
                         <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white mx-auto shadow-lg shadow-emerald-500/20">
                            <CheckCircle2 size={32}/>
                         </div>
                         <div>
                            <h4 className="text-lg font-black uppercase text-emerald-700 dark:text-emerald-400 tracking-tight">Request Confirmed</h4>
                            <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Accessor assigned for {survey.manualType}</p>
                         </div>
                         <p className="text-[0.65rem] text-gray-600 font-medium">
                            Please proceed to finalize the policy. Status will remain <strong>PENDING_SURVEY</strong> until assessment is complete.
                         </p>
                      </div>
                   )}

                   {/* Re-Audit Action (Only if Clean or Rejected or Manual not yet requested) */}
                   {survey.manualRequestStatus === 'NONE' && (
                      <div className="flex justify-center pt-2">
                        <button 
                           onClick={() => { setSurvey({...survey, score: 0, verdict: '', detailedIssues: [], photoFlags: [], underwritingReport: ''}); }}
                           className="px-8 py-3 bg-gray-100 dark:bg-white/5 rounded-full text-[0.6rem] font-black uppercase text-gray-500 dark:text-gray-400 tracking-widest hover:text-primary-500 hover:bg-primary-500/5 transition-all flex items-center gap-3 active:scale-95 shadow-sm border border-black/5"
                        >
                           <RefreshCw size={14} className="animate-spin-slow"/> Recalibrate Neural Data
                        </button>
                      </div>
                   )}
                </div>
              ) : (
                <button 
                  onClick={runSurveyAI}
                  disabled={loading}
                  className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-black rounded-[3rem] font-black uppercase text-base tracking-[0.4em] shadow-[0_30px_60px_rgba(0,0,0,0.3)] flex items-center justify-center gap-6 group active:scale-95 transition-all relative overflow-hidden border border-white/10"
                >
                  <div className="absolute inset-0 bg-primary-500 translate-y-full group-hover:translate-y-0 transition-transform duration-700 opacity-20"></div>
                  {loading ? <Loader2 size={28} className="animate-spin text-primary-500"/> : <Cpu size={32} className="group-hover:rotate-12 transition-transform text-primary-500"/>}
                  <span className="relative z-10">LUNCURKAN AUDIT VISUAL AI</span>
                </button>
              )}
           </div>
        )}
      </div>
    );
  };

  const renderStepFinal = () => {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';
      const summaryItems = [
          { label: 'Unit Kendaraan', value: `${vehicle.brand} ${vehicle.model} (${vehicle.year})`, icon: Car },
          { label: 'Plat / No Polisi', value: stnkResult.plate || vehicle.plate, icon: Smartphone },
          { label: 'Tipe Polis', value: coverage.type, icon: ShieldCheck },
          { label: 'Audit Visual AI', value: `${survey.score}/100`, icon: Gauge, color: survey.score >= 85 ? 'text-emerald-500' : survey.score >= 80 ? 'text-emerald-400' : 'text-amber-500' },
          { label: 'Sync Registry', value: stnkResult.status === 'OK' ? 'VERIFIED' : 'PENDING', icon: LinkIcon },
          { label: 'Underwriting', value: survey.verdict === 'REJECTED' ? 'REJECTED' : (isManualPending ? 'Pending Survey' : 'Instant Issuance'), icon: Cpu, color: survey.verdict === 'REJECTED' ? 'text-rose-500' : (isManualPending ? 'text-amber-500' : 'text-emerald-500') }
      ];

      return (
        <div className="space-y-8 animate-fade-in py-4 pb-20">
          <div className="text-center space-y-4">
            <div className={`w-24 h-24 rounded-[2.5rem] mx-auto flex items-center justify-center text-white shadow-2xl transition-all duration-1000 ${survey.verdict === 'REJECTED' ? 'bg-rose-500 shadow-rose-500/40 rotate-12' : isManualPending ? 'bg-amber-500 shadow-amber-500/40' : 'bg-emerald-500 shadow-emerald-500/40 animate-pop-in'}`}>
              {survey.verdict === 'REJECTED' ? <ShieldX size={48} strokeWidth={3}/> : isManualPending ? <CalendarClock size={48} strokeWidth={3}/> : <CheckCircle2 size={48} strokeWidth={3} />}
            </div>
            <div className="space-y-1">
               <h3 className="text-3xl font-black uppercase tracking-tighter">
                 {survey.verdict === 'REJECTED' ? 'Audit Status: Rejected' : isManualPending ? 'Survey Scheduled' : 'Matrix Policy Ready'}
               </h3>
               <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">
                  {survey.verdict === 'REJECTED' ? 'Registry Node terminated due to risk mismatch.' : isManualPending ? 'Policy issuance pending manual assessment results.' : 'Neural verification successful. Ready for deployment.'}
               </p>
            </div>
          </div>

          <div className="p-10 bg-white dark:bg-white/5 border-2 border-black/5 dark:border-white/5 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.05)] space-y-8 relative overflow-hidden">
             {/* ... (Summary UI) ... */}
             <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none rotate-12"><Smartphone size={240}/></div>
             <div className="grid grid-cols-2 gap-y-10 gap-x-6 relative z-10">
                {summaryItems.map((item, idx) => (
                    <div key={idx} className="space-y-2">
                        <div className="flex items-center gap-3 text-gray-400">
                           <item.icon size={14}/>
                           <span className="text-[0.55rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
                        </div>
                        <p className={`text-[0.95rem] font-black uppercase tracking-tight truncate ${item.color || 'text-gray-900 dark:text-white'}`}>{item.value}</p>
                    </div>
                ))}
             </div>

             <div className="pt-8 border-t border-black/5 dark:border-white/5 flex justify-between items-center relative z-10">
                <div>
                    <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest leading-none mb-1">Final Premium Hub</p>
                    <p className="text-3xl font-black text-primary-500 tracking-tighter leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
                </div>
                <div className="p-5 bg-gray-50 dark:bg-black/40 rounded-[2rem] border border-black/5 shadow-inner">
                   <Shield size={28} className="text-primary-500"/>
                </div>
             </div>
          </div>

          {survey.verdict !== 'REJECTED' ? (
            <button onClick={handleFinalPayment} className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-black rounded-[3rem] font-black uppercase text-base tracking-[0.3em] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.3)] flex items-center justify-center gap-6 transition-all hover:scale-[1.02] active:scale-95 group border border-white/10">
               <Wallet size={28} className="text-primary-500 group-hover:rotate-12 transition-transform"/> 
               {isManualPending ? 'CONFIRM & SCHEDULE' : 'KONFIRMASI PEMBAYARAN'}
            </button>
          ) : (
            <button onClick={() => setStep(0)} className="w-full py-6 bg-rose-500 text-white rounded-[2rem] font-black uppercase text-sm tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all">
               <RefreshCw size={20}/> RE-INITIALIZE REGISTRY
            </button>
          )}
        </div>
      );
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-dark-bg text-gray-900 dark:text-white overflow-hidden relative selection:bg-primary-100">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0 relative z-[100] shadow-sm">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5">
               <div className="w-14 h-14 bg-midnight rounded-[1.8rem] flex items-center justify-center text-white shadow-2xl group border border-white/10"><Car size={28} className="group-hover:rotate-12 transition-transform text-primary-500"/></div>
               <div>
                  <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1.5">Auto-Neural Module</p>
                  <h3 className="text-xl font-black uppercase tracking-tighter leading-none">Sure<span className="text-primary-500">Path</span> Registry</h3>
               </div>
            </div>
            <div className="flex items-center gap-3">
               <button 
                onClick={() => { if(confirm("Restart progress?")) { clearProgress(); window.location.reload(); } }} 
                className="p-3 text-gray-400 hover:text-rose-500 bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5"
               >
                  <RefreshCw size={20}/>
               </button>
               <button onClick={onComplete} className="p-3 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5">
                 <X size={24}/>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl border border-black/5">
                <div className="px-4 py-1.5 text-[0.65rem] font-black text-primary-600 uppercase tracking-widest">{STEPS[step].label}</div>
             </div>
             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2.5">
             {STEPS.map((s, i) => (<div key={i} className={`h-2 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_15px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto px-8 py-10 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && renderStepVehicle()}
            {step === 1 && renderStepCoverage()}
            {step === 2 && renderStepProviders()}
            {step === 3 && renderStepKYC()}
            {step === 4 && renderStepPreSummary()}
            {step === 5 && renderStepSurvey()}
            {step === 6 && renderStepFinal()}
          </div>
       </div>

       <div className="px-8 py-8 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-8 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-20px_50px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.6rem] font-black uppercase text-gray-400 leading-none mb-1.5 tracking-[0.2em]">Matrix Premium Est.</p>
             <p className="text-3xl font-black tracking-tighter text-primary-500 leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-4">
             {step > 0 && (<button onClick={handleBack} className="p-5 bg-gray-50 dark:bg-white/5 rounded-3xl text-gray-400 hover:text-primary-500 transition-all shadow-sm border border-black/5 active:scale-95"><ChevronLeft size={28}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && (survey.score === 0 || (survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus !== 'REQUESTED')))}
                  className="px-12 py-5 bg-midnight dark:bg-white text-white dark:text-black rounded-[1.8rem] font-black uppercase text-[0.75rem] tracking-[0.3em] shadow-2xl transition-all active:scale-95 flex items-center gap-3 disabled:opacity-30 disabled:grayscale group"
                >
                  {step === 5 && survey.manualVerif ? 'Submisi HQ Review' : 'Next Cycle'} <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform"/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

