                    />
                    {verifiedFields.has('address') && (
                        <div className="absolute right-5 bottom-5 text-emerald-500 drop-shadow-sm animate-pop-in">
                            <CheckCircle2 size={18}/>
                        </div>
                    )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

