import React from 'react';
import { 
  FileText, FileSearch, Trash2, User, Camera, Loader2, AlertTriangle, Check, 
  Microscope, BrainCircuit, RefreshCw, Info, Cpu, ShieldCheck, Activity, ShieldX,
  FileSearch as ManualAuditIcon, Video, Car, CalendarClock
} from 'lucide-react';
import { ScannerOverlay } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: string | null;
  setLoadingType: (t: string | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;

      // Optimistic update
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));

      if (file.size > 5 * 1024 * 1024) {
         setPhotoValidation(prev => ({ 
             ...prev, 
             [slotId]: { status: 'INVALID', msg: 'Max File Size 5MB' } 
         }));
         return;
      }

      const img = new Image();
      img.src = base64;
      img.onload = async () => {
          if (img.width < 600 || img.height < 400) {
             setPhotoValidation(prev => ({ 
                 ...prev, 
                 [slotId]: { status: 'INVALID', msg: 'Min Resolution 600x400' } 
             }));
             return;
          }

          setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));

          try {
            const result = await validateVehiclePhoto(base64, slotLabel);
            setPhotoValidation(prev => ({ 
              ...prev, 
              [slotId]: { 
                status: result.valid ? 'VALID' : 'INVALID',
                msg: result.issue
              } 
            }));
          } catch (e) {
            setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } })); // Fallback
          }
      };
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto unit (5 posisi) sebelum memulai audit AI.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const response = await analyzeVehicleSurvey(photoEntries);

    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;
      const needsManual = finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED';
      const isRejected = response.auditVerdict === 'REJECTED';

      setSurvey((prev: any) => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        underwritingReport: response.underwritingReport || '',
        detailedIssues: response.detailedIssues || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (finalScore < 80 ? 'Skor neural di bawah ambang batas otomatis (80). Butuh verifikasi manual.' : ''),
        manualVerif: needsManual && !isRejected
      }));
    }
  };

  const submitManualRequest = () => {
    if (!survey.manualDate) {
        alert("Pilih tanggal survey");
        return;
    }
    setSurvey((prev: any) => ({ ...prev, manualRequestStatus: 'REQUESTED' }));
  };

  const photoSlots = [
    { id: 'front', label: 'Front 45°', desc: 'Depan Serong' },
    { id: 'back', label: 'Rear 45°', desc: 'Belakang Serong' },
    { id: 'right', label: 'Right Side', desc: 'Sisi Kanan' },
    { id: 'left', label: 'Left Side', desc: 'Sisi Kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Interior Depan' }
  ];
  const capturedCount = Object.keys(survey.photos).length;

  const verdictData: any = {
    'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT PASSED', desc: 'Neural scoring within acceptable risk parameters. Immediate issuance enabled.' },
    'REVIEW_REQUIRED': { icon: Activity, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'REVIEW REQ', desc: 'Anomalies detected. Subject to high-fidelity human audit before activation.' },
    'MANUAL_REQUIRED': { icon: ManualAuditIcon, color: 'text-amber-600', bg: 'bg-amber-600/10', label: 'MANUAL AUDIT', desc: 'Neural score below 80 threshold. Physical or video assessment required.' },
    'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'REJECTED', desc: 'Critical integrity breach or damage levels exceed underwriting protocol.' },
  };

  return (
    <div className="space-y-8 animate-fade-in pb-24">
      {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Neural Document Extraction</p></div>
              </div>
              <label className="group relative aspect-[3/1] rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-gray-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="STNK Neural Audit" /> : (
                  <>
                      <FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan Dokumen STNK</p>
                      <input type="file" accept="image/*" capture="environment" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
      ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">STNK Verified: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-gray-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
      )}

      <div className="space-y-4">
        <div className="flex items-center justify-between px-2">
           <div className="flex items-center gap-3">
              <Camera size={16} className="text-primary-500"/>
              <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Visual Evidence Matrix</h4>
           </div>
           <div className="px-3 py-1 bg-primary-500/10 rounded-full text-[0.5rem] font-black text-primary-500 uppercase">{capturedCount}/5 Done</div>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const validation = photoValidation[slot.id];
              const isLoading = validation?.status === 'LOADING';
              const isInvalid = validation?.status === 'INVALID';
              const isValid = validation?.status === 'VALID';

              return (
              <div key={slot.id} className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center gap-2 overflow-hidden shadow-sm ${survey.photos[slot.id] ? (isInvalid ? 'border-rose-500 bg-rose-500/[0.03]' : 'border-primary-500 bg-primary-500/[0.03] border-solid') : 'border-black/10 dark:border-white/10 bg-white dark:bg-white/[0.03]'}`}>
                 {survey.photos[slot.id] ? (
                   <>
                      <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />
                      <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center bg-black/20 backdrop-blur-[2px] transition-opacity duration-500" style={{ opacity: isLoading || isInvalid ? 1 : 0 }}>
                         {isLoading && <div className="flex flex-col items-center gap-2"><Loader2 size={24} className="text-white animate-spin"/><span className="text-[0.5rem] font-black text-white uppercase tracking-widest">Scanning...</span></div>}
                         {isInvalid && <div className="flex flex-col items-center gap-2 p-2 bg-rose-500/90 rounded-xl max-w-[80%]"><AlertTriangle size={18} className="text-white"/><span className="text-[0.45rem] font-black text-white uppercase tracking-widest leading-tight">{validation.msg || 'Invalid Photo'}</span></div>}
                      </div>
                      {isValid && !isLoading && <div className="absolute top-3 right-3 bg-emerald-500 text-white p-1 rounded-full shadow-lg animate-pop-in"><Check size={12} strokeWidth={4}/></div>}
                      <button onClick={() => { const newPhotos = {...survey.photos}; delete newPhotos[slot.id]; setSurvey({...survey, photos: newPhotos, score: 0, verdict: ''}); setPhotoValidation(prev => { const n = {...prev}; delete n[slot.id]; return n; }); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] backdrop-blur-[2px] cursor-pointer pointer-events-auto"><Trash2 size={24}/></button>
                      <div className="absolute top-3 left-3 px-2 py-0.5 bg-black/60 text-white rounded text-[0.45rem] font-black uppercase tracking-widest">{slot.label}</div>
                   </>
                 ) : (
                   <>
                      <Camera size={24} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase text-gray-500">{slot.label}</p>
                      <input type="file" accept="image/*" capture="environment" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const file = e.target.files?.[0]; if (file) handlePhotoUpload(file, slot.id, slot.desc); }} />
                   </>
                 )}
              </div>
           )})}
        </div>
      </div>

      {capturedCount === 5 && survey.stnk && (
         <div className="space-y-6 pt-4">
            {loading && loadingType === 'SURVEY' ? (
              <div className="glass-card rounded-[3rem] p-12 flex flex-col items-center text-center gap-6 shadow-2xl relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-primary-500 animate-scan-fast"></div>
                 <div className="relative"><div className="w-24 h-24 border-4 border-primary-500/20 rounded-full animate-ping opacity-30"></div><div className="absolute inset-0 flex items-center justify-center"><Microscope className="text-primary-500 animate-pulse" size={48} /></div></div>
                 <div className="space-y-2"><p className="text-[0.85rem] font-black uppercase tracking-[0.4em] text-primary-500">Neural Underwriting Active</p><p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Generating Factual Report & Scoring...</p></div>
              </div>
            ) : survey.score > 0 ? (
              <div className="space-y-6 animate-pop-in">
                 <div className={`p-8 rounded-[3rem] border-2 shadow-2xl relative overflow-hidden bg-white dark:bg-[#0a0a0a] ${survey.verdict === 'REJECTED' ? 'border-rose-500/30 shadow-rose-500/5' : survey.verdict === 'MANUAL_REQUIRED' ? 'border-amber-500/30 shadow-amber-500/5' : 'border-emerald-500/30 shadow-emerald-500/5'}`}>
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8 mb-8 relative z-10">
                       <div className="flex items-center gap-6">
                          <div className="relative w-24 h-24 flex items-center justify-center">
                             <svg className="w-full h-full transform -rotate-90">
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={263.8} strokeDashoffset={263.8 - (263.8 * survey.score) / 100} className={`transition-all duration-1000 ${survey.score >= 85 ? 'text-emerald-500 shadow-[0_0_10px_#10b981]' : survey.score >= 80 ? 'text-emerald-400' : 'text-amber-500'}`}/>
                             </svg>
                             <span className="absolute text-3xl font-black">{survey.score}</span>
                          </div>
                          <div className="space-y-1">
                             <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em]">Neural Score Index</p>
                             <h4 className={`text-2xl font-black uppercase tracking-tighter ${verdictData[survey.verdict]?.color}`}>{verdictData[survey.verdict]?.label}</h4>
                             <div className="flex items-center gap-2">
                                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${survey.verdict === 'CLEAN' ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                                <span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{survey.verdict === 'CLEAN' ? 'Instant Approval' : 'Action Required'}</span>
                              </div>
                          </div>
                       </div>
                    </div>

                    <div className="p-6 bg-gray-50 dark:bg-white/[0.02] rounded-[2rem] border border-black/5 dark:border-white/5 relative z-10 space-y-4">
                       <div className="flex items-center gap-3">
                          <FileText size={14} className="text-primary-500"/>
                          <span className="text-[0.55rem] font-black uppercase text-primary-500 tracking-widest">Neural Underwriting Report</span>
                       </div>
                       <p className="text-[0.65rem] font-bold text-gray-600 dark:text-gray-300 leading-relaxed">
                          {survey.underwritingReport || "Report generated based on visual evidence."}
                       </p>

                       {survey.detailedIssues && survey.detailedIssues.length > 0 && (
                          <div className="space-y-2 pt-2 border-t border-black/5 dark:border-white/5">
                             <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Detected Imperfections</p>
                             {survey.detailedIssues.map((issue: any, idx: number) => (
                                <div key={idx} className="flex justify-between items-start text-[0.6rem] bg-white dark:bg-black/20 p-2 rounded-lg border border-black/5">
                                   <span className="font-bold text-gray-700 dark:text-gray-200">{issue.part}: {issue.description}</span>
                                   <span className="text-rose-500 font-black uppercase text-[0.5rem]">{issue.severity}</span>
                                </div>
                             ))}
                          </div>
                       )}
                    </div>
                 </div>

                 {survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus === 'NONE' && (
                    <div className="p-6 bg-amber-50 dark:bg-amber-900/10 rounded-[2.5rem] border border-amber-200 dark:border-amber-900/30 space-y-6">
                       <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-amber-500 rounded-xl flex items-center justify-center text-white shadow-lg"><ManualAuditIcon size={20}/></div>
                          <div>
                             <h4 className="text-sm font-black uppercase text-amber-700 dark:text-amber-400 tracking-wide">Manual Assessment Required</h4>
                             <p className="text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest">Score under 80 threshold</p>
                          </div>
                       </div>
                       <p className="text-[0.65rem] text-gray-600 dark:text-gray-300 font-medium">
                          Based on our strict neural underwriting, visual evidence shows conditions that require human verification. Please schedule a manual survey to proceed.
                       </p>

                       <div className="grid grid-cols-2 gap-3">
                          <button onClick={() => setSurvey({...survey, manualType: 'VIDEO'})} className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${survey.manualType === 'VIDEO' ? 'border-amber-500 bg-amber-500/10 text-amber-600' : 'border-black/5 text-gray-400'}`}>
                             <Video size={20}/>
                             <span className="text-[0.55rem] font-black uppercase tracking-widest">Video Call</span>
                          </button>
                          <button onClick={() => setSurvey({...survey, manualType: 'PHYSICAL'})} className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${survey.manualType === 'PHYSICAL' ? 'border-amber-500 bg-amber-500/10 text-amber-600' : 'border-black/5 text-gray-400'}`}>
                             <Car size={20}/>
                             <span className="text-[0.55rem] font-black uppercase tracking-widest">Home Visit</span>
                          </button>
                       </div>

                       <div className="space-y-2">
                          <label className="text-[0.55rem] font-black uppercase text-gray-500 tracking-widest">Preferred Date & Time</label>
                          <div className="relative">
                             <CalendarClock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"/>
                             <input 
                                type="datetime-local" 
                                className="w-full pl-10 pr-4 py-3 bg-white dark:bg-white/5 border border-black/10 rounded-xl text-xs font-bold outline-none focus:border-amber-500"
                                onChange={(e) => setSurvey({...survey, manualDate: e.target.value})}
                             />
                          </div>
                       </div>

                       <button onClick={submitManualRequest} className="w-full py-4 bg-amber-500 text-white rounded-xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-lg active:scale-95 transition-all">
                          Confirm Survey Request
                       </button>
                    </div>
                 )}

                 {survey.manualRequestStatus === 'REQUESTED' && (
                    <div className="p-6 bg-emerald-50 dark:bg-emerald-900/10 rounded-[2.5rem] border border-emerald-200 dark:border-emerald-900/30 text-center space-y-4">
                       <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white mx-auto shadow-lg shadow-emerald-500/20">
                          <CheckCircle2 size={32}/>
                       </div>
                       <div>
                          <h4 className="text-lg font-black uppercase text-emerald-700 dark:text-emerald-400 tracking-tight">Request Confirmed</h4>
                          <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Accessor assigned for {survey.manualType}</p>
                       </div>
                       <p className="text-[0.65rem] text-gray-600 font-medium">
                          Please proceed to finalize the policy. Status will remain <strong>PENDING_SURVEY</strong> until assessment is complete.
                       </p>
                    </div>
                 )}

                 {survey.manualRequestStatus === 'NONE' && (
                    <div className="flex justify-center pt-2">
                      <button 
                         onClick={() => { setSurvey({...survey, score: 0, verdict: '', detailedIssues: [], photoFlags: [], underwritingReport: ''}); }}
                         className="px-8 py-3 bg-gray-100 dark:bg-white/5 rounded-full text-[0.6rem] font-black uppercase text-gray-500 dark:text-gray-400 tracking-widest hover:text-primary-500 hover:bg-primary-500/5 transition-all flex items-center gap-3 active:scale-95 shadow-sm border border-black/5"
                      >
                         <RefreshCw size={14} className="animate-spin-slow"/> Recalibrate Neural Data
                      </button>
                    </div>
                 )}
              </div>
            ) : (
              <button 
                onClick={runSurveyAI}
                disabled={loading}
                className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-black rounded-[3rem] font-black uppercase text-base tracking-[0.4em] shadow-[0_30px_60px_rgba(0,0,0,0.3)] flex items-center justify-center gap-6 group active:scale-95 transition-all relative overflow-hidden border border-white/10"
              >
                <div className="absolute inset-0 bg-primary-500 translate-y-full group-hover:translate-y-0 transition-transform duration-700 opacity-20"></div>
                {loading ? <Loader2 size={28} className="animate-spin text-primary-500"/> : <Cpu size={32} className="group-hover:rotate-12 transition-transform text-primary-500"/>}
                <span className="relative z-10">LUNCURKAN AUDIT VISUAL AI</span>
              </button>
            )}
         </div>
      )}
    </div>
  );
};

export default StepSurvey;

import React from 'react';
import { 
  Car, Smartphone, ShieldCheck, Gauge, Link as LinkIcon, Cpu, 
  ShieldX, CalendarClock, CheckCircle2, Shield, Wallet, RefreshCw 
} from 'lucide-react';
import { formatIDR } from './WizardUI';

interface StepFinalProps {
  vehicle: any;
  stnkResult: any;
  coverage: any;
  survey: any;
  premiumBreakdown: any;
  handleFinalPayment: () => void;
  setStep: (s: number) => void;
}

const StepFinal: React.FC<StepFinalProps> = ({
  vehicle, stnkResult, coverage, survey, premiumBreakdown, handleFinalPayment, setStep
}) => {
  const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';
  const summaryItems = [
      { label: 'Unit Kendaraan', value: `${vehicle.brand} ${vehicle.model} (${vehicle.year})`, icon: Car },
      { label: 'Plat / No Polisi', value: stnkResult.plate || vehicle.plate, icon: Smartphone },
      { label: 'Tipe Polis', value: coverage.type, icon: ShieldCheck },
      { label: 'Audit Visual AI', value: `${survey.score}/100`, icon: Gauge, color: survey.score >= 85 ? 'text-emerald-500' : survey.score >= 80 ? 'text-emerald-400' : 'text-amber-500' },
      { label: 'Sync Registry', value: stnkResult.status === 'OK' ? 'VERIFIED' : 'PENDING', icon: LinkIcon },
      { label: 'Underwriting', value: survey.verdict === 'REJECTED' ? 'REJECTED' : (isManualPending ? 'Pending Survey' : 'Instant Issuance'), icon: Cpu, color: survey.verdict === 'REJECTED' ? 'text-rose-500' : (isManualPending ? 'text-amber-500' : 'text-emerald-500') }
  ];

  return (
    <div className="space-y-8 animate-fade-in py-4 pb-20">
      <div className="text-center space-y-4">
        <div className={`w-24 h-24 rounded-[2.5rem] mx-auto flex items-center justify-center text-white shadow-2xl transition-all duration-1000 ${survey.verdict === 'REJECTED' ? 'bg-rose-500 shadow-rose-500/40 rotate-12' : isManualPending ? 'bg-amber-500 shadow-amber-500/40' : 'bg-emerald-500 shadow-emerald-500/40 animate-pop-in'}`}>
          {survey.verdict === 'REJECTED' ? <ShieldX size={48} strokeWidth={3}/> : isManualPending ? <CalendarClock size={48} strokeWidth={3}/> : <CheckCircle2 size={48} strokeWidth={3} />}
        </div>
        <div className="space-y-1">
           <h3 className="text-3xl font-black uppercase tracking-tighter">
             {survey.verdict === 'REJECTED' ? 'Audit Status: Rejected' : isManualPending ? 'Survey Scheduled' : 'Matrix Policy Ready'}
           </h3>
           <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">
              {survey.verdict === 'REJECTED' ? 'Registry Node terminated due to risk mismatch.' : isManualPending ? 'Policy issuance pending manual assessment results.' : 'Neural verification successful. Ready for deployment.'}
           </p>
        </div>
      </div>

      <div className="p-10 bg-white dark:bg-white/5 border-2 border-black/5 dark:border-white/5 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.05)] space-y-8 relative overflow-hidden">
         <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none rotate-12"><Smartphone size={240}/></div>
         <div className="grid grid-cols-2 gap-y-10 gap-x-6 relative z-10">
            {summaryItems.map((item, idx) => (
                <div key={idx} className="space-y-2">
                    <div className="flex items-center gap-3 text-gray-400">
                       <item.icon size={14}/>
                       <span className="text-[0.55rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
                    </div>
                    <p className={`text-[0.95rem] font-black uppercase tracking-tight truncate ${item.color || 'text-gray-900 dark:text-white'}`}>{item.value}</p>
                </div>
            ))}
         </div>

         <div className="pt-8 border-t border-black/5 dark:border-white/5 flex justify-between items-center relative z-10">
            <div>
                <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest leading-none mb-1">Final Premium Hub</p>
                <p className="text-3xl font-black text-primary-500 tracking-tighter leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
            </div>
            <div className="p-5 bg-gray-50 dark:bg-black/40 rounded-[2rem] border border-black/5 shadow-inner">
               <Shield size={28} className="text-primary-500"/>
            </div>
         </div>
      </div>

      {survey.verdict !== 'REJECTED' ? (
        <button onClick={handleFinalPayment} className="w-full py-8 bg-midnight dark:bg-white text-white dark:text-black rounded-[3rem] font-black uppercase text-base tracking-[0.3em] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.3)] flex items-center justify-center gap-6 transition-all hover:scale-[1.02] active:scale-95 group border border-white/10">
           <Wallet size={28} className="text-primary-500 group-hover:rotate-12 transition-transform"/> 
           {isManualPending ? 'CONFIRM & SCHEDULE' : 'KONFIRMASI PEMBAYARAN'}
        </button>
      ) : (
        <button onClick={() => setStep(0)} className="w-full py-6 bg-rose-500 text-white rounded-[2rem] font-black uppercase text-sm tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all">
           <RefreshCw size={20}/> RE-INITIALIZE REGISTRY
        </button>
      )}
    </div>
  );
};

export default StepFinal;

import React, { useState, useMemo, useEffect } from 'react';
import { Car, RefreshCw, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, INSURANCE_PROVIDERS } from '../constants';
import { InsuranceType } from '../types';
import { db, Policy, Transaction } from '../db';
import { DamageIssue, PhotoFlag } from '../services/geminiService';
import { formatIDR } from './car-wizard/WizardUI';

// Import Steps
import StepVehicle from './car-wizard/StepVehicle';
import StepCoverage from './car-wizard/StepCoverage';
import StepProviders from './car-wizard/StepProviders';
import StepKYC from './car-wizard/StepKYC';
import StepPreSummary from './car-wizard/StepPreSummary';
import StepSurvey from './car-wizard/StepSurvey';
import StepFinal from './car-wizard/StepFinal';

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'PRESUMMARY', label: 'Rincian' },
  { id: 'SURVEY', label: 'Audit' },
  { id: 'FINAL', label: 'Bayar' }
];

const STORAGE_KEY = 'SUREPATH_CAR_WIZARD_PROGRESS';

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'KTP' | 'STNK' | 'SURVEY' | null>(null);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    underwritingReport: '',
    detailedIssues: [] as DamageIssue[], 
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | 'MANUAL_REQUIRED' | '',
    rejectionReason: '',
    manualVerif: false, 
    manualRequestStatus: 'NONE' as 'NONE' | 'REQUESTED',
    manualDate: '',
    manualType: 'VIDEO' as 'VIDEO' | 'PHYSICAL',
    accessories: '' 
  });

  const [photoValidation, setPhotoValidation] = useState<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>({});

  // --- PERSISTENCE LOGIC ---
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        if (data.step !== undefined) setStep(data.step);
        if (data.vehicle) setVehicle(data.vehicle);
        if (data.coverage) setCoverage(data.coverage);
        if (data.selectedProviderId) setSelectedProviderId(data.selectedProviderId);
        if (data.kycData) setKycData(data.kycData);
        if (data.survey) setSurvey(data.survey);
        if (data.stnkResult) setStnkResult(data.stnkResult);
      } catch (err) {
        console.error("Failed to restore wizard progress", err);
      }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const stateToSave = {
        step,
        vehicle,
        coverage,
        selectedProviderId,
        kycData,
        survey,
        stnkResult
      };
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
      } catch (err) {
        console.warn("Storage quota exceeded");
      }
    }, 1000); 
    return () => clearTimeout(timer);
  }, [step, vehicle, coverage, selectedProviderId, kycData, survey, stnkResult]);

  const clearProgress = () => {
    localStorage.removeItem(STORAGE_KEY);
  };

  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const netPremium = basicPremium + expansionTotal;

    return {
        baseRate, basicPremium, expansions, tplPremium,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const sortedProviders = useMemo(() => {
    return [...INSURANCE_PROVIDERS].sort((a, b) => {
      if (sortBy === 'RATING') return b.rating - a.rating;
      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
  }, [sortBy, premiumBreakdown]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleFinalPayment = async () => {
    if (!currentUser || !premiumBreakdown) return;

    try {
      const isManualPending = survey.verdict === 'MANUAL_REQUIRED' || survey.manualRequestStatus === 'REQUESTED';

      const newPolicy: Policy = {
        userId: currentUser.id,
        type: 'CAR',
        status: isManualPending ? 'PENDING' : 'ACTIVE',
        startDate: new Date().toISOString(),
        endDate: new Date(new Date().setFullYear(new Date().getFullYear() + 1)).toISOString(),
        premium: premiumBreakdown.totalPayable,
        providerId: selectedProviderId || '',
        policyNumber: `POL-CR-${Date.now()}`,
        createdAt: new Date().toISOString(),
        coverageDetails: {
          vehicle: { ...vehicle, ...stnkResult },
          coverage: coverage,
          survey: survey
        }
      };

      const policyId = await db.policies.add(newPolicy);

      const newTransaction: Transaction = {
        userId: currentUser.id,
        type: 'PAYMENT',
        amount: premiumBreakdown.totalPayable,
        status: isManualPending ? 'PENDING' : 'SUCCESS',
        description: `Payment for Policy ${newPolicy.policyNumber}`,
        date: new Date().toISOString(),
        referenceId: policyId.toString()
      };

      await db.transactions.add(newTransaction);

      clearProgress();
      onComplete();
    } catch (e) {
      console.error("DB Error", e);
      alert("Gagal memproses pembayaran. Coba lagi.");
    }
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-dark-bg text-gray-900 dark:text-white overflow-hidden relative selection:bg-primary-100">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0 relative z-[100] shadow-sm">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5">
               <div className="w-14 h-14 bg-midnight rounded-[1.8rem] flex items-center justify-center text-white shadow-2xl group border border-white/10"><Car size={28} className="group-hover:rotate-12 transition-transform text-primary-500"/></div>
               <div>
                  <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1.5">Auto-Neural Module</p>
                  <h3 className="text-xl font-black uppercase tracking-tighter leading-none">Sure<span className="text-primary-500">Path</span> Registry</h3>
               </div>
            </div>
            <div className="flex items-center gap-3">
               <button 
                onClick={() => { if(confirm("Restart progress?")) { clearProgress(); window.location.reload(); } }} 
                className="p-3 text-gray-400 hover:text-rose-500 bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5"
               >
                  <RefreshCw size={20}/>
               </button>
               <button onClick={onComplete} className="p-3 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-50 dark:bg-white/5 rounded-2xl transition-all border border-black/5">
                 <X size={24}/>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl border border-black/5">
                <div className="px-4 py-1.5 text-[0.65rem] font-black text-primary-600 uppercase tracking-widest">{STEPS[step].label}</div>
             </div>
             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2.5">
             {STEPS.map((s, i) => (<div key={i} className={`h-2 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_15px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto px-8 py-10 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && (
                <StepVehicle 
                    vehicle={vehicle} setVehicle={setVehicle} 
                    entryMode={entryMode} setEntryMode={setEntryMode} 
                    handlePlateChange={handlePlateChange} formatInputCurrency={formatInputCurrency} 
                />
            )}
            {step === 1 && <StepCoverage coverage={coverage} setCoverage={setCoverage} />}
            {step === 2 && (
                <StepProviders 
                    sortBy={sortBy} setSortBy={setSortBy} 
                    sortedProviders={sortedProviders} selectedProviderId={selectedProviderId} 
                    setSelectedProviderId={setSelectedProviderId} premiumBreakdown={premiumBreakdown} 
                    showProviderBreakdown={showProviderBreakdown} setShowProviderBreakdown={setShowProviderBreakdown} 
                />
            )}
            {step === 3 && (
                <StepKYC 
                    kycData={kycData} setKycData={setKycData} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    verifiedFields={verifiedFields} setVerifiedFields={setVerifiedFields} 
                />
            )}
            {step === 4 && (
                <StepPreSummary 
                    vehicle={vehicle} coverage={coverage} 
                    premiumBreakdown={premiumBreakdown} showBreakdown={showBreakdown} 
                    setShowBreakdown={setShowBreakdown} 
                />
            )}
            {step === 5 && (
                <StepSurvey 
                    survey={survey} setSurvey={setSurvey} 
                    stnkResult={stnkResult} setStnkResult={setStnkResult} 
                    loading={loading} setLoading={setLoading} 
                    loadingType={loadingType} setLoadingType={setLoadingType} 
                    photoValidation={photoValidation} setPhotoValidation={setPhotoValidation} 
                    vehicle={vehicle} 
                />
            )}
            {step === 6 && (
                <StepFinal 
                    vehicle={vehicle} stnkResult={stnkResult} 
                    coverage={coverage} survey={survey} 
                    premiumBreakdown={premiumBreakdown} handleFinalPayment={handleFinalPayment} 
                    setStep={setStep} 
                />
            )}
          </div>
       </div>

       <div className="px-8 py-8 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-8 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-20px_50px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.6rem] font-black uppercase text-gray-400 leading-none mb-1.5 tracking-[0.2em]">Matrix Premium Est.</p>
             <p className="text-3xl font-black tracking-tighter text-primary-500 leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-4">
             {step > 0 && (<button onClick={handleBack} className="p-5 bg-gray-50 dark:bg-white/5 rounded-3xl text-gray-400 hover:text-primary-500 transition-all shadow-sm border border-black/5 active:scale-95"><ChevronLeft size={28}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && (survey.score === 0 || (survey.verdict === 'MANUAL_REQUIRED' && survey.manualRequestStatus !== 'REQUESTED')))}
                  className="px-12 py-5 bg-midnight dark:bg-white text-white dark:text-black rounded-[1.8rem] font-black uppercase text-[0.75rem] tracking-[0.3em] shadow-2xl transition-all active:scale-95 flex items-center gap-3 disabled:opacity-30 disabled:grayscale group"
                >
                  {step === 5 && survey.manualVerif ? 'Submisi HQ Review' : 'Next Cycle'} <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform"/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;

import React from 'react';
import { 
  FileText, FileSearch, Trash2, User, Camera, Loader2, AlertTriangle, Check, 
  Microscope, BrainCircuit, RefreshCw, Info, Cpu, ShieldCheck, Activity, ShieldX,
  FileSearch as ManualAuditIcon, Video, Car, CalendarClock, CheckCircle2
} from 'lucide-react';
import { ScannerOverlay } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: string | null;
  setLoadingType: (t: string | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;

      // Optimistic update
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));

      if (file.size > 5 * 1024 * 1024) {
         setPhotoValidation(prev => ({ 
             ...prev, 
             [slotId]: { status: 'INVALID', msg: 'Max File Size 5MB' } 
         }));
         return;
      }

      const img = new Image();
      img.src = base64;
      img.onload = async () => {
          if (img.width < 600 || img.height < 400) {
             setPhotoValidation(prev => ({ 
                 ...prev, 
                 [slotId]: { status: 'INVALID', msg: 'Min Resolution 600x400' } 
             }));
             return;
          }

          setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));

          try {
            const result = await validateVehiclePhoto(base64, slotLabel);
            setPhotoValidation(prev => ({ 
              ...prev, 
              [slotId]: { 
                status: result.valid ? 'VALID' : 'INVALID',
                msg: result.issue
              } 
            }));
          } catch (e) {
            setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } })); // Fallback
          }
      };
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto unit (5 posisi) sebelum memulai audit AI.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const response = await analyzeVehicleSurvey(photoEntries);

    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;
      const needsManual = finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED';
      const isRejected = response.auditVerdict === 'REJECTED';

      setSurvey((prev: any) => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        underwritingReport: response.underwritingReport || '',
        detailedIssues: response.detailedIssues || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (finalScore < 80 ? 'Skor neural di bawah ambang batas otomatis (80). Butuh verifikasi manual.' : ''),
        manualVerif: needsManual && !isRejected
      }));
    }
  };

  const submitManualRequest = () => {
    if (!survey.manualDate) {
        alert("Pilih tanggal survey");
        return;
    }
    setSurvey((prev: any) => ({ ...prev, manualRequestStatus: 'REQUESTED' }));
  };

  const photoSlots = [
    { id: 'front', label: 'Front 45°', desc: 'Depan Serong' },
    { id: 'back', label: 'Rear 45°', desc: 'Belakang Serong' },
    { id: 'right', label: 'Right Side', desc: 'Sisi Kanan' },
    { id: 'left', label: 'Left Side', desc: 'Sisi Kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Interior Depan' }
  ];
  const capturedCount = Object.keys(survey.photos).length;

  const verdictData: any = {
    'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT PASSED', desc: 'Neural scoring within acceptable risk parameters. Immediate issuance enabled.' },
    'REVIEW_REQUIRED': { icon: Activity, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'REVIEW REQ', desc: 'Anomalies detected. Subject to high-fidelity human audit before activation.' },
    'MANUAL_REQUIRED': { icon: ManualAuditIcon, color: 'text-amber-600', bg: 'bg-amber-600/10', label: 'MANUAL AUDIT', desc: 'Neural score below 80 threshold. Physical or video assessment required.' },
    'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'REJECTED', desc: 'Critical integrity breach or damage levels exceed underwriting protocol.' },
  };

  return (
    <div className="space-y-8 animate-fade-in pb-24">
      {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Neural Document Extraction</p></div>
              </div>
              <label className="group relative aspect-[3/1] rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-gray-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="STNK Neural Audit" /> : (
                  <>
                      <FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan Dokumen STNK</p>
                      <input type="file" accept="image/*" capture="environment" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
      ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">STNK Verified: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-gray-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
      )}

      <div className="space-y-4">
        <div className="flex items-center justify-between px-2">
           <div className="flex items-center gap-3">
              <Camera size={16} className="text-primary-500"/>
              <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Visual Evidence Matrix</h4>
           </div>
           <div className="px-3 py-1 bg-primary-500/10 rounded-full text-[0.5rem] font-black text-primary-500 uppercase">{capturedCount}/5 Done</div>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const validation = photoValidation[slot.id];
              const isLoading = validation?.status === 'LOADING';
              const isInvalid = validation?.status === 'INVALID';
              const isValid = validation?.status === 'VALID';

              return (
              <div key={slot.id} className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center gap-2 overflow-hidden shadow-sm ${survey.photos[slot.id] ? (isInvalid ? 'border-rose-500 bg-rose-500/[0.03]' : 'border-primary-500 bg-primary-500/[0.03] border-solid') : 'border-black/10 dark:border-white/10 bg-white dark:bg-white/[0.03]'}`}>
                 {survey.photos[slot.id] ? (
                   <>
                      <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />
                      <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center bg-black/20 backdrop-blur-[2px] transition-opacity duration-500" style={{ opacity: isLoading || isInvalid ? 1 : 0 }}>
                         {isLoading && <div className="flex flex-col items-center gap-2"><Loader2 size={24} className="text-white animate-spin"/><span className="text-[0.5rem] font-black text-white uppercase tracking-widest">Scanning...</span></div>}
                         {isInvalid && <div className="flex flex-col items-center gap-2 p-2 bg-rose-500/90 rounded-xl max-w-[80%]"><AlertTriangle size={18} className="text-white"/><span className="text-[0.45rem] font-black text-white uppercase tracking-widest leading-tight">{validation.msg || 'Invalid Photo'}</span></div>}
                      </div>
                      {isValid && !isLoading && <div className="absolute top-3 right-3 bg-emerald-500 text-white p-1 rounded-full shadow-lg animate-pop-in"><Check size={12} strokeWidth={4}/></div>}
                      <button onClick={() => { const newPhotos = {...survey.photos}; delete newPhotos[slot.id]; setSurvey({...survey, photos: newPhotos, score: 0, verdict: ''}); setPhotoValidation(prev => { const n = {...prev}; delete n[slot.id]; return n; }); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] backdrop-blur-[2px] cursor-pointer pointer-events-auto"><Trash2 size={24}/></button>
                      <div className="absolute top-3 left-3 px-2 py-0.5 bg-black/60 text-white rounded text-[0.45rem] font-black uppercase tracking-widest">{slot.label}</div>
                   </>
                 ) : (
                   <>
                      <Camera size={24} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase text-gray-500">{slot.label}</p>
                      <input type="file" accept="image/*" capture="environment" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const file = e.target.files?.[0]; if (file) handlePhotoUpload(file, slot.id, slot.desc); }} />
                   </>
                 )}
              </div>
           )})}
        </div>
      </div>

      {capturedCount === 5 && survey.stnk && (
         <div className="space-y-6 pt-4">
            {loading && loadingType === 'SURVEY' ? (
              <div className="glass-card rounded-[3rem] p-12 flex flex-col items-center text-center gap-6 shadow-2xl relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-primary-500 animate-scan-fast"></div>
                 <div className="relative"><div className="w-24 h-24 border-4 border-primary-500/20 rounded-full animate-ping opacity-30"></div><div className="absolute inset-0 flex items-center justify-center"><Microscope className="text-primary-500 animate-pulse" size={48} /></div></div>
                 <div className="space-y-2"><p className="text-[0.85rem] font-black uppercase tracking-[0.4em] text-primary-500">Neural Underwriting Active</p><p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Generating Factual Report & Scoring...</p></div>
              </div>
            ) : survey.score > 0 ? (
              <div className="space-y-6 animate-pop-in">
                 <div className={`p-8 rounded-[3rem] border-2 shadow-2xl relative overflow-hidden bg-white dark:bg-[#0a0a0a] ${survey.verdict === 'REJECTED' ? 'border-rose-500/30 shadow-rose-500/5' : survey.verdict === 'MANUAL_REQUIRED' ? 'border-amber-500/30 shadow-amber-500/5' : 'border-emerald-500/30 shadow-emerald-500/5'}`}>
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8 mb-8 relative z-10">
                       <div className="flex items-center gap-6">
                          <div className="relative w-24 h-24 flex items-center justify-center">
                             <svg className="w-full h-full transform -rotate-90">
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={263.8} strokeDashoffset={263.8 - (263.8 * survey.score) / 100} className={`transition-all duration-1000 ${survey.score >= 85 ? 'text-emerald-500 shadow-[0_0_10px_#10b981]' : survey.score >= 80 ? 'text-emerald-400' : 'text-amber-500'}`}/>
                             </svg>
                             <span className="absolute text-3xl font-black">{survey.score}</span>
                          </div>
                          <div className="space-y-1">
                             <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em]">Neural Score Index</p>
                             <h4 className={`text-2xl font-black uppercase tracking-tighter ${verdictData[survey.verdict]?.color}`}>{verdictData[survey.verdict]?.label}</h4>
                             <div className="flex items-center gap-2">
                                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${survey.verdict === 'CLEAN' ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                                <span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{survey.verdict === 'CLEAN' ? 'Instant Approval' : 'Action Required'}</span>
                              </div>
                          </div>
                       </div>
                    </div>

                    <div className="p-6 bg-gray-50 dark:bg-white/[0.02] rounded-[2rem] border border-black/5 dark:border-white/5 relative z-10 space-y-4">
                       <div className="flex items-center gap-3">
                          <FileText size={14} className="text-primary-500"/>
                          <span className="text-[0.55rem] font-black uppercase text-primary-500 tracking-widest">Neural Underwriting Report</span>
                       </div>
                       <p className="text-[0.65rem] font-bold text-gray-600 dark:text-gray-300 leading-relaxed">
                          {survey.underwritingReport || "Report generated based on visual evidence."}
                       </p>

                       {survey.detailedIssues && survey.detailedIssues.length > 0 && (
                          <div className="space-y-2 pt-2 border-t border-black/5 dark:border-white/5">
                             <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Detected Imperfections</p>
