                  <Plus size={18} strokeWidth={4}/>
                </div>
              </div>
              <div className="space-y-1.5">
                <p className="text-[0.8rem] font-black uppercase tracking-[0.2em] text-gray-900 dark:text-white">Upload KTP Asli</p>
                <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest opacity-60">Automated Neural OCR Extraction</p>
              </div>
              <input 
                type="file" 
                accept="image/*"
                capture="environment"
                className="absolute inset-0 opacity-0 cursor-pointer"
                onChange={async (e) => {
                  const file = e.target.files?.[0];
                  if (!file) return;
                  setLoading(true);
                  setLoadingType('KTP');
                  const reader = new FileReader();
                  reader.onload = async () => {
                    const base64 = reader.result as string;
                    setKycData((prev: any) => ({ ...prev, photo: base64 }));
                    const response = await extractKtpData(base64);
                    setLoading(false);
                    setLoadingType(null);
                    if (response.success && response.data) {
                      const newVerified = new Set<string>();
                      if (response.data.name) newVerified.add('name');
                      if (response.data.nik) newVerified.add('ktp');
                      if (response.data.address) newVerified.add('address');
                      setVerifiedFields(newVerified);
                      setKycData((prev: any) => ({
                        ...prev,
                        name: response.data.name?.toUpperCase() || prev.name,
                        ktp: response.data.nik || prev.ktp,
                        address: response.data.address?.toUpperCase() || prev.address
                      }));
                    }
                  };
                  reader.readAsDataURL(file);
                }}
              />
            </>
