import React from 'react';
import { 
  FileText, FileSearch, Trash2, User, Camera, Loader2, AlertTriangle, Check, 
  Microscope, BrainCircuit, RefreshCw, Info, Cpu, ShieldCheck, Activity, ShieldX,
  FileSearch as ManualAuditIcon, Video, Car, CalendarClock, CheckCircle2
} from 'lucide-react';
import { ScannerOverlay } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;

      // Optimistic update
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));

      if (file.size > 5 * 1024 * 1024) {
         setPhotoValidation(prev => ({ 
             ...prev, 
             [slotId]: { status: 'INVALID', msg: 'Max File Size 5MB' } 
         }));
         return;
      }

      const img = new Image();
      img.src = base64;
      img.onload = async () => {
          if (img.width < 600 || img.height < 400) {
             setPhotoValidation(prev => ({ 
                 ...prev, 
                 [slotId]: { status: 'INVALID', msg: 'Min Resolution 600x400' } 
             }));
             return;
          }

          setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));

          try {
            const result = await validateVehiclePhoto(base64, slotLabel);
            setPhotoValidation(prev => ({ 
              ...prev, 
              [slotId]: { 
                status: result.valid ? 'VALID' : 'INVALID',
                msg: result.issue
              } 
            }));
          } catch (e) {
            setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } })); // Fallback
          }
      };
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto unit (5 posisi) sebelum memulai audit AI.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const response = await analyzeVehicleSurvey(photoEntries);

    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;
      const needsManual = finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED';
      const isRejected = response.auditVerdict === 'REJECTED';

      setSurvey((prev: any) => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        underwritingReport: response.underwritingReport || '',
        detailedIssues: response.detailedIssues || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (finalScore < 80 ? 'Skor neural di bawah ambang batas otomatis (80). Butuh verifikasi manual.' : ''),
        manualVerif: needsManual && !isRejected
      }));
    }
  };

  const submitManualRequest = () => {
    if (!survey.manualDate) {
        alert("Pilih tanggal survey");
        return;
    }
    setSurvey((prev: any) => ({ ...prev, manualRequestStatus: 'REQUESTED' }));
  };

  const photoSlots = [
    { id: 'front', label: 'Front 45°', desc: 'Depan Serong' },
    { id: 'back', label: 'Rear 45°', desc: 'Belakang Serong' },
    { id: 'right', label: 'Right Side', desc: 'Sisi Kanan' },
    { id: 'left', label: 'Left Side', desc: 'Sisi Kiri' },
    { id: 'interior', label: 'Dashboard', desc: 'Interior Depan' }
  ];
  const capturedCount = Object.keys(survey.photos).length;

  const verdictData: any = {
    'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT PASSED', desc: 'Neural scoring within acceptable risk parameters. Immediate issuance enabled.' },
    'REVIEW_REQUIRED': { icon: Activity, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'REVIEW REQ', desc: 'Anomalies detected. Subject to high-fidelity human audit before activation.' },
    'MANUAL_REQUIRED': { icon: ManualAuditIcon, color: 'text-amber-600', bg: 'bg-amber-600/10', label: 'MANUAL AUDIT', desc: 'Neural score below 80 threshold. Physical or video assessment required.' },
    'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'REJECTED', desc: 'Critical integrity breach or damage levels exceed underwriting protocol.' },
  };

  return (
    <div className="space-y-8 animate-fade-in pb-24">
      {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Neural Document Extraction</p></div>
              </div>
              <label className="group relative aspect-[3/1] rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-gray-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="STNK Neural Audit" /> : (
                  <>
                      <FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan Dokumen STNK</p>
                      <input type="file" accept="image/*" capture="environment" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
      ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">STNK Verified: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-gray-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
      )}

      <div className="space-y-4">
        <div className="flex items-center justify-between px-2">
           <div className="flex items-center gap-3">
              <Camera size={16} className="text-primary-500"/>
              <h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Visual Evidence Matrix</h4>
           </div>
           <div className="px-3 py-1 bg-primary-500/10 rounded-full text-[0.5rem] font-black text-primary-500 uppercase">{capturedCount}/5 Done</div>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const validation = photoValidation[slot.id];
              const isLoading = validation?.status === 'LOADING';
              const isInvalid = validation?.status === 'INVALID';
              const isValid = validation?.status === 'VALID';

              return (
              <div key={slot.id} className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center gap-2 overflow-hidden shadow-sm ${survey.photos[slot.id] ? (isInvalid ? 'border-rose-500 bg-rose-500/[0.03]' : 'border-primary-500 bg-primary-500/[0.03] border-solid') : 'border-black/10 dark:border-white/10 bg-white dark:bg-white/[0.03]'}`}>
                 {survey.photos[slot.id] ? (
                   <>
                      <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />
                      <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center bg-black/20 backdrop-blur-[2px] transition-opacity duration-500" style={{ opacity: isLoading || isInvalid ? 1 : 0 }}>
                         {isLoading && <div className="flex flex-col items-center gap-2"><Loader2 size={24} className="text-white animate-spin"/><span className="text-[0.5rem] font-black text-white uppercase tracking-widest">Scanning...</span></div>}
                         {isInvalid && <div className="flex flex-col items-center gap-2 p-2 bg-rose-500/90 rounded-xl max-w-[80%]"><AlertTriangle size={18} className="text-white"/><span className="text-[0.45rem] font-black text-white uppercase tracking-widest leading-tight">{validation.msg || 'Invalid Photo'}</span></div>}
                      </div>
                      {isValid && !isLoading && <div className="absolute top-3 right-3 bg-emerald-500 text-white p-1 rounded-full shadow-lg animate-pop-in"><Check size={12} strokeWidth={4}/></div>}
                      <button onClick={() => { const newPhotos = {...survey.photos}; delete newPhotos[slot.id]; setSurvey({...survey, photos: newPhotos, score: 0, verdict: ''}); setPhotoValidation(prev => { const n = {...prev}; delete n[slot.id]; return n; }); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] backdrop-blur-[2px] cursor-pointer pointer-events-auto"><Trash2 size={24}/></button>
                      <div className="absolute top-3 left-3 px-2 py-0.5 bg-black/60 text-white rounded text-[0.45rem] font-black uppercase tracking-widest">{slot.label}</div>
                   </>
                 ) : (
                   <>
                      <Camera size={24} className="text-gray-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase text-gray-500">{slot.label}</p>
                      <input type="file" accept="image/*" capture="environment" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const file = e.target.files?.[0]; if (file) handlePhotoUpload(file, slot.id, slot.desc); }} />
                   </>
                 )}
              </div>
           )})}
        </div>
      </div>

      {capturedCount === 5 && survey.stnk && (
         <div className="space-y-6 pt-4">
            {loading && loadingType === 'SURVEY' ? (
              <div className="glass-card rounded-[3rem] p-12 flex flex-col items-center text-center gap-6 shadow-2xl relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-primary-500 animate-scan-fast"></div>
                 <div className="relative"><div className="w-24 h-24 border-4 border-primary-500/20 rounded-full animate-ping opacity-30"></div><div className="absolute inset-0 flex items-center justify-center"><Microscope className="text-primary-500 animate-pulse" size={48} /></div></div>
                 <div className="space-y-2"><p className="text-[0.85rem] font-black uppercase tracking-[0.4em] text-primary-500">Neural Underwriting Active</p><p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Generating Factual Report & Scoring...</p></div>
              </div>
            ) : survey.score > 0 ? (
              <div className="space-y-6 animate-pop-in">
                 <div className={`p-8 rounded-[3rem] border-2 shadow-2xl relative overflow-hidden bg-white dark:bg-[#0a0a0a] ${survey.verdict === 'REJECTED' ? 'border-rose-500/30 shadow-rose-500/5' : survey.verdict === 'MANUAL_REQUIRED' ? 'border-amber-500/30 shadow-amber-500/5' : 'border-emerald-500/30 shadow-emerald-500/5'}`}>
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8 mb-8 relative z-10">
                       <div className="flex items-center gap-6">
                          <div className="relative w-24 h-24 flex items-center justify-center">
                             <svg className="w-full h-full transform -rotate-90">
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                                <circle cx="48" cy="48" r="42" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={263.8} strokeDashoffset={263.8 - (263.8 * survey.score) / 100} className={`transition-all duration-1000 ${survey.score >= 85 ? 'text-emerald-500 shadow-[0_0_10px_#10b981]' : survey.score >= 80 ? 'text-emerald-400' : 'text-amber-500'}`}/>
                             </svg>
                             <span className="absolute text-3xl font-black">{survey.score}</span>
                          </div>
                          <div className="space-y-1">
                             <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em]">Neural Score Index</p>
                             <h4 className={`text-2xl font-black uppercase tracking-tighter ${verdictData[survey.verdict]?.color}`}>{verdictData[survey.verdict]?.label}</h4>
                             <div className="flex items-center gap-2">
                                <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${survey.verdict === 'CLEAN' ? 'bg-emerald-500' : 'bg-amber-500'}`}></div>
                                <span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{survey.verdict === 'CLEAN' ? 'Instant Approval' : 'Action Required'}</span>
                              </div>
                          </div>
                       </div>
                    </div>

                    <div className="p-6 bg-gray-50 dark:bg-white/[0.02] rounded-[2rem] border border-black/5 dark:border-white/5 relative z-10 space-y-4">
                       <div className="flex items-center gap-3">
                          <FileText size={14} className="text-primary-500"/>
                          <span className="text-[0.55rem] font-black uppercase text-primary-500 tracking-widest">Neural Underwriting Report</span>
                       </div>
                       <p className="text-[0.65rem] font-bold text-gray-600 dark:text-gray-300 leading-relaxed">
                          {survey.underwritingReport || "Report generated based on visual evidence."}
                       </p>

                       {survey.detailedIssues && survey.detailedIssues.length > 0 && (
                          <div className="space-y-2 pt-2 border-t border-black/5 dark:border-white/5">
